import React, { useEffect, useState } from "react";
import http from "../../services/utility";
import { apisPath, paths } from "../../utils/path";
import { useNavigate } from "react-router-dom";
import { useDispatch } from "react-redux";
import { openSuccessTicker } from "../../redux/reducer/SuccessTickerReducer";
import { openTicker } from "../../redux/reducer/ErrorTickerReducer";

export default function BlogList() {
  const navigate = useNavigate();
  const dispatch = useDispatch();

  const [cardData, setCardData] = useState([]);

  useEffect(() => {
    getData();
  }, []);

  const getData = async () => {
    await http
      .get(apisPath?.admin?.blogs)
      .then(async (res) => {
        let data = res?.data?.blogs;
        for (let i = 0; i < data.length; i++) {
          const firstDate = new Date(data[i]?.createdAt);
          const secondDate = new Date();
          data[i]["days_ago"] = Math.floor(
            (secondDate - firstDate) / (1000 * 60 * 60 * 24)
          );
        }
        setCardData(data);
      })
      .catch((err) => {
        console.log(err);
      });
  };
  const deleteData = async (index) => {
    await http
      .delete(`${apisPath?.admin?.blogs}/${index}`)
      .then(async (res) => {
        // console.log(res?.data?.message);
        dispatch(
          openSuccessTicker({ title: "Success", body: res?.data?.message })
        );
        getData();
      })
      .catch((err) => {
        // console.log(err);
        dispatch(
          openTicker({ title: "Error", body: err?.response?.data?.message })
        );
      });
  };

  return (
    <div className="blog_list">
      <h3 className="blog_list__heading page_heading">Blogs</h3>
      <div className="blog_list__content">
        <div className="blog_list__content__blogs_list">
          <h4 className="blog_list__heading page_subheading">
            Blogs list{" "}
            <button
              className="button-red"
              onClick={() =>
                navigate(
                  `/${paths?.front?.user?.blogs}/${paths?.front?.user?.add_blogs}`
                )
              }
            >
              Add Blog
            </button>
          </h4>
          <div className="blog_list__content__blogs_list__content">
            <div className="blog_list__content__blogs_list__content__cards">
              {cardData?.length > 0 ? (
                cardData?.map((card, index) => {
                  return (
                    <BlogListCard
                      data={card}
                      key={index}
                      deleteData={() => deleteData(card?.id)}
                    />
                  );
                })
              ) : (
                <div className="no_data_found">No Data Found</div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

const BlogListCard = ({ data, deleteData }) => {
  const navigate = useNavigate();
  const [imageBg, setImageBg] = useState(data?.images[0]);

  useEffect(() => {
    console.log(data);
  }, []);

  return (
    <div className="blog_list_card">
      <div
        className="blog_list_card__content_container"
        style={{
          background: `rgba(0,0,0,0.4) url("${imageBg}") center / cover no-repeat`,
        }}
      >
        <div className="blog_list_card__content_container__content">
          <div className="blog_list_card__content_container__content__tag_ago_time">
            <span className="add_blogs__content__cards__about__content__tags">
              {data?.tags?.map((tag, index) => {
                return (
                  <span
                    className="add_blogs__content__cards__about__content__tags__tag"
                    key={index}
                  >
                    {tag}
                  </span>
                );
              })}
            </span>
            <p>
              {data?.days_ago} days ago <span>.</span> {data?.duration} read
            </p>
          </div>
          <h3>{data?.heading}</h3>
          <span>
            {data?.bodyText?.length > 150
              ? data?.bodyText?.substring(0, 150) + "..."
              : data?.bodyText}
          </span>
        </div>
      </div>
      <button className="button-red" onClick={deleteData}>
        Delete
      </button>
      <button
        className="button-red"
        onClick={() =>
          navigate(
            `/${paths?.front?.user?.blogs}/${paths?.front?.user?.add_blogs}`,
            {
              state: { data: data, blogId: data?.id, editable: true },
            }
          )
        }
      >
        Edit
      </button>
    </div>
  );
};
